377	    /**
378	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
379	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
380	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
381	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
382	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
383	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
384	     *
385	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
386	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
387	     *
388	     * @param telephone the raw telephone value, possibly {@code null}
389	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
390	     */
391	    private String toE164(String telephone) {
392	        if (telephone == null) {
393	            return null;
394	        }
395	        String cleaned = telephone.replaceAll("[ \\-()]", "");
396	        String digits;
397	        if (cleaned.startsWith("+")) {
398	            digits = cleaned.substring(1);
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            digits = "61" + national;
402	        }
403	        if (!digits.matches("[0-9]{8,15}")) {
404	            return null;
405	        }
406	        if (!nationalNumberLengthValid(digits)) {
407	            return null;
408	        }
409	        return "+" + digits;
410	    }
411	
412	    /**
413	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
414	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
415	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
416	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
417	     * accepted, leaving only the generic total-length rule to apply.
418	     *
419	     * @param digits the E.164 digits without the leading {@code '+'}
420	     * @return {@code true} if the national-number length matches the country code's requirement
421	     */
422	    private boolean nationalNumberLengthValid(String digits) {
423	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
424	            String code = entry.getKey();
425	            if (digits.startsWith(code)) {
426	                return digits.length() - code.length() == entry.getValue();
427	            }
428	        }
429	        return true;
430	    }
