452	    /**
453	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
454	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
455	     * owner's normalized telephone, email (empty when absent) and household id joined with
456	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
457	     * owner's. Because the telephone is part of the key, two members of the same household
458	     * (same {@code householdId}) with different telephones have different identity keys and are both
459	     * allowed.
460	     *
461	     * @param owner the owner being created, with its normalized telephone, email and household id set
462	     * @throws DuplicateIdentityException if another owner already has this identity key
463	     */
464	    private void requireUniqueIdentity(Owner owner) {
465	        String identityKey = owner.getIdentityKey();
466	        boolean inUse = this.clinicService.findAllOwners().stream()
467	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
468	        if (inUse) {
469	            throw new DuplicateIdentityException(identityKey);
470	        }
471	    }
