504	    /**
505	     * Rejects a create that would join an existing household unless it has opted in via
506	     * {@code sharesHousehold}. The household is keyed on the deterministic {@code householdId} (derived
507	     * from the normalized last name and postcode; see {@link #computeHouseholdId}), so any existing
508	     * owner carrying the same {@code householdId} is a member of the same household. When one exists and
509	     * the create has not declared household membership, the second owner is a household duplicate.
510	     *
511	     * <p>A create that declares {@code sharesHousehold} bypasses this block entirely and is created as a
512	     * declared household member.
513	     *
514	     * @param owner the owner being created, with its deterministic {@code householdId} already set
515	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
516	     * @throws DuplicateHouseholdException if an existing owner already shares the household and the
517	     *     create did not declare {@code sharesHousehold}
518	     */
519	    private void requireNoHouseholdDuplicate(Owner owner, boolean declaredHouseholdMember) {
520	        if (declaredHouseholdMember) {
521	            return;
522	        }
523	        String householdId = owner.getHouseholdId();
524	        boolean inUse = this.clinicService.findAllOwners().stream()
525	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
526	        if (inUse) {
527	            throw new DuplicateHouseholdException(householdId);
528	        }
529	    }
