531	    /**
532	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
533	     * the household - the existing owners that share the deterministic {@code householdId} and the new
534	     * one - so the shared size can be read back from any of them. The count is the number of existing
535	     * members plus the owner being created.
536	     *
537	     * @param owner the owner being created, with its deterministic {@code householdId} already set
538	     */
539	    private void stampHouseholdSize(Owner owner) {
540	        String householdId = owner.getHouseholdId();
541	        List<Owner> members = this.clinicService.findAllOwners().stream()
542	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
543	            .toList();
544	        int householdSize = members.size() + 1;
545	        owner.setHouseholdSize(householdSize);
546	        for (Owner member : members) {
547	            member.setHouseholdSize(householdSize);
548	            this.clinicService.saveOwner(member);
549	        }
550	    }
