552	    /**
553	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
554	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
555	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
556	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
557	     * shares a last name and postcode computes the same identifier and therefore the same household.
558	     *
559	     * @param lastName the last name of the household
560	     * @param postcode the postcode of the household, possibly {@code null}
561	     * @return the 12-character upper-case hex household identifier
562	     */
563	    private String computeHouseholdId(String lastName, String postcode) {
564	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
565	        try {
566	            byte[] digest = MessageDigest.getInstance("SHA-256")
567	                .digest(key.getBytes(StandardCharsets.UTF_8));
568	            StringBuilder hex = new StringBuilder(12);
569	            for (int i = 0; i < 6; i++) {
570	                hex.append(String.format("%02X", digest[i]));
571	            }
572	            return hex.toString();
573	        } catch (NoSuchAlgorithmException e) {
574	            throw new IllegalStateException("SHA-256 algorithm not available", e);
575	        }
576	    }
