578	    /**
579	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
580	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
581	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
582	     *
583	     * @param value the raw value, possibly {@code null}
584	     * @return the normalized value
585	     */
586	    private String normalizeForHousehold(String value) {
587	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
588	    }
589	
590	    /**
591	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
592	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
593	     * value yields an empty string.
594	     *
595	     * @param value the raw value, possibly {@code null}
596	     * @return the trimmed, whitespace-collapsed value
597	     */
598	    private String collapseWhitespace(String value) {
599	        if (value == null) {
600	            return "";
601	        }
602	        return value.trim().replaceAll("\\s+", " ");
603	    }
604	
605	    /**
606	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
607	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
608	     * is upper-cased, and common street-type abbreviations are expanded as whole words
609	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
610	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
611	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
612	     *
613	     * @param address the raw address value, possibly {@code null}
614	     * @return the normalized address
615	     */
616	    private String normalizeAddress(String address) {
617	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
618	        if (collapsed.isEmpty()) {
619	            return "";
620	        }
621	        String[] tokens = collapsed.split(" ");
622	        StringBuilder normalized = new StringBuilder();
623	        for (int i = 0; i < tokens.length; i++) {
624	            if (i > 0) {
625	                normalized.append(' ');
626	            }
627	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
628	        }
629	        return normalized.toString();
630	    }
